mapper.select:
select r.`id`, r.`target_type`, r.`target_id`, r.`reporter_id`, r.`report_reason`,
       r.`report_type`, r.`status`, r.`handler_note`, r.`create_time`, r.`update_time`,
       case when r.target_type = 1 then bc.comment_content else bcr.reply_content end as targetContent,
       u1.username as reporterName,
       case when r.target_type = 1 then u2.username else u3.username end as commenterName
from comment_report r
left join book_comment bc on r.target_type = 1 and r.target_id = bc.id
left join book_comment_reply bcr on r.target_type = 2 and r.target_id = bcr.id
left join user u1 on r.reporter_id = u1.id
left join user u2 on bc.create_user_id = u2.id
left join user u3 on bcr.create_user_id = u3.id

     and r.id = #{id} 
     and r.target_type = #{targetType} 
     and r.report_type = #{reportType} 
     and r.status = #{status} 
     and r.reporter_id = #{reporterId} 



        order by ${sort} ${order}


        order by r.create_time desc



    limit #{offset}, #{limit}

select count(*) from comment_report r

     and r.id = #{id} 
     and r.target_type = #{targetType} 
     and r.report_type = #{reportType} 
     and r.status = #{status} 
     and r.reporter_id = #{reporterId}
